"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5929"],{8338(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>h,frontMatter:()=>a,contentTitle:()=>s,toc:()=>c,assets:()=>d});var i=JSON.parse('{"id":"reference/monitor/howtos/subscriptiondates","title":"Understanding Subscription Dates for Services in ALMS","description":"almsc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/monitor/howtos/subscriptiondates.md","sourceDirName":"reference/monitor/howtos","slug":"/reference/monitor/howtos/subscriptiondates","permalink":"/personal-av-docs/docs/reference/monitor/howtos/subscriptiondates","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/monitor/howtos/subscriptiondates.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Understanding Subscription Dates for Services in ALMS","sidebar_label":"Understanding Subscription Dates for Ser","sidebar_position":99,"edition":"almsc","source":"https://doc.airvantage.net/almsc/reference/monitor/howtos/subscriptiondates","format":"md"}}'),r=n(4848),o=n(8453);let a={title:"Understanding Subscription Dates for Services in ALMS",sidebar_label:"Understanding Subscription Dates for Ser",sidebar_position:99,edition:"almsc",source:"https://doc.airvantage.net/almsc/reference/monitor/howtos/subscriptiondates",format:"md"},s,d={},c=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(t.p,{children:[":::note Edition\n",(0,r.jsx)(t.strong,{children:"almsc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,r.jsx)(t.a,{href:"https://doc.airvantage.net/almsc/reference/monitor/howtos/subscriptiondates",children:"Original page"}),".\n:::"]}),"\n",(0,r.jsxs)(t.p,{children:["Understanding Subscription Dates for Services in ALMS\nOverview\nALMS is the management system for AirLink routers and gateways and provides detailed information on the state of the services (such as AirLink Complete) that are associated with those devices. This page provides an overview on how to find and interpret the information that ALMS displays about the services on your devices.\nThere are four dates that can have data and/or be displayed in ALMS, depending on the offers in your account and which gateway or router model(s) you have deployed:\nSupport Expiry Date\n: The date on which your eligibility for access to Semtech Customer Support ends. This date is valid for AirLink Complete and AirLink Premium offers.\nWarranty Date\n: The date on which your hardware warranty expires for your router or gateway. The default is  one year but can be extended up to 5 years through renewal on AirLink Complete or AirLink Premium.\nGateway End Date\n: The date on which your services expire for AirLink Basic offers for your routers and gateways.\nSubscription End Date\n: The date on which your subscription expires for connectivity-related products (e.g. SIM cards). This date is not likely to be populated for Pre-paid offers.\nThese dates are displayed in two locations: in the\nMonitor > Systems\nGrid and in the System Info widget on the Device Page.\nInitializing Table Of Contents...\nDisplaying in the Monitor > Systems Grid\nWithin the\nMonitor > Systems\nGrid, there are four columns that display this information. For ALMS accounts, Support Expiry Date, Warranty Date and Gateway End Date are displayed by default. Subscription End Date is not enabled by default on ALMS accounts, but can be added by users at any time.\nThe column manager with the relevant columns highlighted is shown here.\nAll columns can be sorted and filtered as required.\nAn ALMS account with AirLink Complete pre-paid offers enabled is shown below. For devices with AirLink Complete, the Support Date and Gateway End Date will display the same information, so only one needs to be shown.\nAn ALMS account with AirLink Basic pre-paid offers enabled is shown below. As AirLink Basic does not provide customer Support, the \u201CSupport Date\u201D column is not populated.\nDisplaying in the System Info Widget\nALMS displays the dates discussed in the System Info widget (which you can view by going to\nMonitor > Systems\nand then selecting a system).\nThe dates applicable to a router on AirLink Complete are shown below.\nThe dates applicable to a router on Airlink Basic are shown below.\nThere are four fields that provide the information about the state of services on the device. After you register a new router, the Support Expiry Date and Warranty Date will be identical for the first year of service (both the warranty and Airlink Complete are valid for 1 year from registration). After renewing AirLink Complete, the Support Expiry Date and Warranty Date will update to reflect the renewal period. You can also renew the warranty up to a maximum of five years but access to Customer Support can be renewed indefinitely.\nOffer\n: Displays the offer that is active on the device. See below for more information on Offers.\nAirLink Complete\n: Displays the offer associated with the device and the state of the offer. It should be active but could indicate if the offer has expired.\nSupport Expiry Date\n: Displays the date that the support element of the service is set to expire. If expired, the device is not eligible for Customer Support. This field will be populated if the offer has a Customer Support component (e.g. AirLink Complete, AirLink Premium). It will display a \u201C \u2013 \u201C if there is no support element to the offer, as is the case for AirLink Basic.\nWarranty Date\n: Displays the date that the hardware warranty will expire for the device. The hardware Warranty Date should typically align with the Support Expiry Date. Current hardware comes with 1-year of hardware warranty, but can be extended to a maximum of 5 years in total by extending AirLink Complete or AirLink Premium. As some older services may have had a 3-year warranty, in some cases the hardware Warranty Date may exceed the Support Expiry Date.\nIntroduction to Offers\nWithin the new ALMS accounts, you have two options to pay for your subscriptions:\nPre-Paid\n(through your Semtech Partner) or\nDirect Billing\n(direct with Sierra Wireless). The majority of accounts, and the default account configuration is Pre-Paid with your Partner. All new ALMS accounts only support one type of offer.\nOffers define the services that are available on an AirLink device. This includes access to ALMS, the level of Customer Support, and can also include connectivity or other services. The Offer includes a service term (typically one, three or, five years) and are often tied to specific device types. For example, the AirLink Complete (XR80) offer can only be used with AirLink XR80 devices. It will never be displayed as a valid offer for any other device type.\nWhen a new ALMS account is created, there are a minimum of four default offers in the account. These offers are tied to different devices, and include:\nAirLink Basic\n: Provides access to ALMS only. No Customer Support or warranty extension. Only available on AirLink LX, MP, and RV devices. AirLink Basic is not available for initial registration, only renewals.\nAirLink Complete\n: Provides access to ALMS, Customer Support, and hardware warranty extension (maximum five years) for as long as the subscription is renewed. Only available on AirLink LX, MP, RV, and RX devices.\nAirLink Complete (XR80)\n: Provides access to ALMS, Customer Support, Out of Band Management (OOBM) connectivity, and hardware warranty extension (maximum five years) for as long as the subscription is renewed. Only available on the AirLink XR80.\nAirLink Premium\n: Provides access to ALMS, Customer Support, OOBM connectivity, Advanced Mobility Reporting (AMR), and hardware warranty extension (maximum five years) for as long as the subscription is renewed. Only available for registration on the AirLink XR90; available for upgrade on the AirLink XR80.\nAccounts set-up with Direct Billing Offers will have additional default offers added to the account to support Semtech connectivity services. These offers vary depending on the location (EU versus NA) of the ALMS account. In addition, we can customize offers for customers that need a unique set of features.\nThe primary difference in the display for accounts that have Direct Billing offers is that the Support Expiry Date will not display an actual value. As support is active on the device as long as payment is made each month, support will remain \u201Cactive\u201D and display this way in the System Info widget.\nThe System Info widget for Direct Billing offers is shown below.\nHow to Renew my Subscriptions\nSemtech will notify your account administrator(s) by email 90 days before the support and warranty dates expire for the first router in your account. Semtech recommends that you do a full fleet renewal. Please work with your Semtech Partner or the Semtech Renewals Team (\n",(0,r.jsx)(t.a,{href:"mailto:renewals-SWI@semtech.com",children:"renewals-SWI@semtech.com"}),"\n) to renew your services and maintain access to your devices on ALMS.\nA sample of the email that is sent to all Adminstrators on an account is shown here.\nCustomers can also review the state of their account within ALMS to understand when their account is set to renew. The\nRenewals\ntab in the Administration interface will display the expected renewal date for your account. This date is set based on the device(s) in the account with the closest expiration date.\nYou can also create a preliminary renewal price quote from the\nRenewals\ntab. See\nHow to Create a Renewal Quote\nfor more information.\nThe\nRenewals\ntab will display the date when your account needs to be renewed."]})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>s});var i=n(6540);let r={},o=i.createContext(r);function a(e){let t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);